import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const resources = [];

  // Plane geometry: 512x320 atlas region → 1.6:1 aspect ratio
  const planeWidth = 1.6;
  const planeHeight = 1.0;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);
  resources.push(geometry);

  // Load and configure texture
  const imageTexture = ctx.textureLoader.load(config.assets.imageUrl);
  imageTexture.colorSpace = THREE.SRGBColorSpace;
  resources.push(imageTexture);

  // Create TSL-based material
  const textureNode = texture(imageTexture);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: textureNode,
    transparent: true,
    side: THREE.DoubleSide,
  });
  resources.push(material);

  // Create and position mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(-3.2, 1, 0.06);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);
  group.add(mesh);

  // Render text overlay via fontAtlas
  if (ctx.fontAtlas && config.textContent && config.textContent.length > 0) {
    const textConfig = config.textContent[0];
    const textSize = 0.39; // 39px converted to scene units

    const textMesh = ctx.fontAtlas.render({
      text: textConfig.text || "Features 1",
      size: textSize,
      weight: textConfig.weight || 400,
      family: 'Lora',
      color: config.colors.ink,
    });

    if (textMesh) {
      textMesh.position.set(-planeWidth * 0.3, planeHeight * 0.3, 0.01);
      mesh.add(textMesh);
      resources.push(textMesh);
    }
  }

  // Cleanup resources
  group.userData.cleanup = () => {
    resources.forEach(res => {
      if (res && typeof res.dispose === 'function') {
        res.dispose();
      }
    });
    gsap.killTweensOf(group);
  };

  // Event handlers (empty; no interactions specified)
  group.userData.handlers = {};

  return group;
}
